use crate::*;
use super::{policy,update};
use std::{collections::BTreeMap,io::Read};
pub async fn manifest(core:&Core,candidate:&Value)->Result<Value>{
 let archive=&candidate["archive"];let hash=string(archive,"sha1")?;if hash.len()!=40||!hash.bytes().all(|b|b.is_ascii_hexdigit()){return Err("整合包归档缺少有效 SHA-1，无法安全预览更新。".into());}
 if archive["size"].as_u64().unwrap_or(u64::MAX)>256*1024*1024{return Err("更新归档超过 256 MB 预览上限，请手动导入。".into());}
 let path=policy::under(&core.root,&format!("cache/agent-pack-archives/{hash}.zip"))?;engine::download(core,string(archive,"url")?,&path,hash).await?;
 let mut zip=zip::ZipArchive::new(std::fs::File::open(path).map_err(err)?).map_err(|_|"更新归档损坏")?;
 let mr=candidate["provider"]=="modrinth";let name=if mr{"modrinth.index.json"}else{"manifest.json"};let index:Value={let file=zip.by_name(name).map_err(|_|"更新归档缺少清单")?;if file.size()>10*1024*1024{return Err("更新清单超过大小上限".into());}serde_json::from_reader(file).map_err(|_|"更新清单 JSON 无效")?};
 let mut files=BTreeMap::new();let mut bytes=0u64;
 for file in index["files"].as_array().ok_or("更新归档文件清单无效")?{core.stopped()?;if mr{if file["env"]["client"]=="unsupported"{continue;}let path=string(file,"path")?;if !update::managed_path(path){return Err("更新清单包含非白名单路径，请手动检查发行包。".into());}policy::under(&core.root,path)?;bytes=bytes.saturating_add(file["fileSize"].as_u64().unwrap_or(0));files.insert(path.to_owned(),json!({"sha256":file["hashes"]["sha256"],"sha1":file["hashes"]["sha1"],"size":file["fileSize"]}));}else{
  let pid=file["projectID"].as_u64().ok_or("更新清单项目 ID 无效")?;let vid=file["fileID"].as_u64().ok_or("更新清单文件 ID 无效")?;let key=curseforge::configured_key(core,"");let metadata=curseforge::file_by_id(core,pid,vid,key.as_deref()).await?;let name=curseforge::file_name(&metadata)?;let kind=if name.to_ascii_lowercase().ends_with(".jar"){"mods"}else{let project=curseforge::project_info(core,pid,key.as_deref()).await?;match project["classId"].as_u64(){Some(12)=>"resourcepacks",Some(6552)=>"shaderpacks",_=>return Err("更新含无法识别侧别的资源，请手动导入核对。".into())}};let path=format!("{kind}/{name}");bytes=bytes.saturating_add(metadata["fileLength"].as_u64().unwrap_or(0));files.insert(path,json!({"sha1":curseforge::file_hash(&metadata),"size":metadata["fileLength"]}));
 }}
 let override_root=index["overrides"].as_str().unwrap_or("overrides");if override_root.contains('\\')||override_root.contains(':')||override_root.split('/').any(|s|s==".."||s=="."){return Err("更新覆盖目录不安全".into());}
 for prefix in [format!("{override_root}/"),"client-overrides/".into()]{for n in 0..zip.len(){core.stopped()?;let mut file=zip.by_index(n).map_err(err)?;if file.is_dir(){continue;}let Some(path)=file.name().strip_prefix(&prefix).map(str::to_owned)else{continue};if !update::managed_path(&path){continue;}policy::under(&core.root,&path)?;if file.size()>64*1024*1024||files.len()>20000{return Err("更新覆盖文件过大或数量超限".into());}use sha2::{Digest,Sha256};let mut hash=Sha256::new();let mut buf=[0u8;65536];loop{let len=file.read(&mut buf).map_err(err)?;if len==0{break;}hash.update(&buf[..len]);}bytes=bytes.saturating_add(file.size());files.insert(path,json!({"sha256":format!("{:x}",hash.finalize()),"size":file.size()}));}}
 if files.keys().filter(|p|p.starts_with("mods/")&&p.ends_with(".jar")).count()>80||bytes>policy::MAX_BYTES{return Err("新整合包超过 80 模组或 2 GB 预算，请选择更轻量版本。".into());}
 Ok(json!({"files":files,"downloadBytes":bytes,"minecraft":if mr{&index["dependencies"]["minecraft"]}else{&index["minecraft"]["version"]}}))
}
pub fn differences(root:&Path,baseline:&BTreeMap<String,String>,next:&Value)->Result<Value>{let files=next.as_object().ok_or("更新文件清单无效")?;let current=update::inventory(root)?;let mut added=Vec::new();let mut changed=Vec::new();let mut removed=Vec::new();let mut preserved=Vec::new();for(path,metadata)in files{let Some(hash)=current.get(path)else{added.push(path.clone());continue};let same=if let Some(next)=metadata["sha256"].as_str(){next.eq_ignore_ascii_case(hash)}else if let Some(next)=metadata["sha1"].as_str(){use sha1::{Digest,Sha1};let mut source=std::fs::File::open(policy::under(root,path)?).map_err(err)?;let mut sha=Sha1::new();let mut buf=[0u8;65536];loop{let n=source.read(&mut buf).map_err(err)?;if n==0{break;}sha.update(&buf[..n]);}format!("{:x}",sha.finalize()).eq_ignore_ascii_case(next)}else{false};if !same{changed.push(path.clone());}if path=="options.txt"||path.starts_with("config/")||path.starts_with("defaultconfigs/")||baseline.get(path)!=Some(hash){preserved.push(path.clone());}}
 for(path,hash)in &current{if files.contains_key(path){continue;}if baseline.get(path)==Some(hash)&&!path.starts_with("config/")&&!path.starts_with("defaultconfigs/")&&path!="options.txt"{removed.push(path.clone());}else{preserved.push(path.clone());}}
 Ok(json!({"added":added,"changed":changed,"removed":removed,"preserved":preserved}))}
#[cfg(test)]mod tests{use super::*;#[test]fn diff_lists_changed_removed_and_user_preservation(){let t=tempfile::tempdir().unwrap();std::fs::create_dir(t.path().join("mods")).unwrap();std::fs::write(t.path().join("mods/old.jar"),b"old").unwrap();std::fs::write(t.path().join("mods/user.jar"),b"user").unwrap();let mut baseline=update::inventory(t.path()).unwrap();baseline.remove("mods/user.jar");let next=json!({"mods/new.jar":{"sha256":"x"},"mods/user.jar":{"sha256":"different"}});let d=differences(t.path(),&baseline,&next).unwrap();assert_eq!(d["added"],json!(["mods/new.jar"]));assert_eq!(d["removed"],json!(["mods/old.jar"]));assert_eq!(d["preserved"],json!(["mods/user.jar"]));assert!(super::super::snapshot::hash(&t.path().join("mods/user.jar")).is_ok());}}
